"""Rank function and topological ordering of a proof DAG."""
from __future__ import annotations
from typing import Dict, List, Set

Graph = Dict[str, List[str]]

def reachable(graph: Graph, start: str) -> Set[str]:
    seen: Set[str] = set()
    stack = list(graph.get(start, []))
    while stack:
        x = stack.pop()
        if x not in seen:
            seen.add(x)
            stack.extend(graph.get(x, []))
    return seen

def rank(graph: Graph) -> Dict[str, int]:
    """f(v) = number of statements reaching v (Topological Numbering Theorem)."""
    anc: Dict[str, int] = {v: 0 for v in graph}
    for u in graph:
        for v in reachable(graph, u):
            anc[v] += 1
    return anc

def topo_order(graph: Graph) -> List[str]:
    return sorted(graph, key=lambda v: rank(graph)[v])

if __name__ == "__main__":
    g: Graph = {"Ax": ["L1", "L2"], "L1": ["Thm"], "L2": ["Thm"], "Thm": []}
    print("ranks:", rank(g))
    print("valid teaching order:", topo_order(g))

"""Kahn's algorithm: topological order with circular-argument detection."""
from __future__ import annotations
from collections import deque
from typing import Dict, List, Optional

Graph = Dict[str, List[str]]

def kahn(graph: Graph) -> Optional[List[str]]:
    """Return a topological order, or None if the graph has a cycle."""
    indeg: Dict[str, int] = {v: 0 for v in graph}
    for outs in graph.values():
        for w in outs:
            indeg[w] += 1
    # sources: in-degree 0 (guaranteed to exist if nonempty & acyclic)
    queue = deque(v for v in graph if indeg[v] == 0)
    order: List[str] = []
    while queue:
        v = queue.popleft()
        order.append(v)
        for w in graph.get(v, []):
            indeg[w] -= 1
            if indeg[w] == 0:
                queue.append(w)
    return order if len(order) == len(graph) else None

if __name__ == "__main__":
    good: Graph = {"A": ["B", "C"], "B": ["D"], "C": ["D"], "D": []}
    bad: Graph = {"A": ["B"], "B": ["C"], "C": ["A"]}
    print("acyclic  ->", kahn(good))
    print("circular ->", kahn(bad), "(None = circular argument detected)")

"""Proof depth: the longest dependency chain (critical path) of a DAG."""
from __future__ import annotations
from typing import Dict, List, Tuple

Graph = Dict[str, List[str]]

def proof_depth(graph: Graph) -> Tuple[int, List[str]]:
    memo: Dict[str, Tuple[int, List[str]]] = {}
    def best(v: str) -> Tuple[int, List[str]]:
        if v in memo:
            return memo[v]
        res = (1, [v])
        for w in graph.get(v, []):
            length, path = best(w)
            if 1 + length > res[0]:
                res = (1 + length, [v] + path)
        memo[v] = res
        return res
    overall = (0, [])
    for v in graph:
        length, path = best(v)
        if length > overall[0]:
            overall = (length, path)
    return overall

if __name__ == "__main__":
    g: Graph = {"Ax": ["A", "B"], "A": ["C"], "B": ["C"], "C": ["Cap"], "Cap": []}
    d, p = proof_depth(g)
    print("proof depth:", d)
    print("critical path:", " -> ".join(p))

