"""Draw a proof DAG in topological layers ranked by ancestor count."""
import matplotlib.pyplot as plt
from typing import Dict, List, Set

Graph = Dict[str, List[str]]

def reachable(g: Graph, s: str) -> Set[str]:
    seen: Set[str] = set(); stack = list(g.get(s, []))
    while stack:
        x = stack.pop()
        if x not in seen:
            seen.add(x); stack.extend(g.get(x, []))
    return seen

def ranks(g: Graph) -> Dict[str, int]:
    r = {v: 0 for v in g}
    for u in g:
        for v in reachable(g, u):
            r[v] += 1
    return r

G: Graph = {"Axioms": ["Induction", "Order"], "Induction": ["AddAssoc", "MulComm"],
            "Order": ["MulComm", "WellOrder"], "AddAssoc": ["Distributivity"],
            "MulComm": ["Distributivity"], "WellOrder": ["Distributivity"],
            "Distributivity": ["FundThmArith"], "FundThmArith": []}

r = ranks(G)
layers: Dict[int, List[str]] = {}
for v, k in r.items():
    layers.setdefault(k, []).append(v)
pos: Dict[str, tuple] = {}
for k, nodes in layers.items():
    for i, v in enumerate(sorted(nodes)):
        pos[v] = (i - (len(nodes) - 1) / 2, k)

fig, ax = plt.subplots(figsize=(8, 6))
for u, outs in G.items():
    for w in outs:
        x1, y1 = pos[u]; x2, y2 = pos[w]
        ax.annotate("", xy=(x2, y2), xytext=(x1, y1),
                    arrowprops=dict(arrowstyle="->", color="#888", lw=1.3))
for v, (x, y) in pos.items():
    ax.scatter([x], [y], s=1400, c="#4C72B0", zorder=3)
    ax.text(x, y, v, ha="center", va="center", color="white", fontsize=7, zorder=4)
ax.set_ylabel("rank  f(v) = |ancestors(v)|")
ax.set_title("Proof DAG laid out by topological rank")
ax.set_xticks([]); ax.margins(0.15)
plt.tight_layout(); plt.savefig("proofdag_layers.png", dpi=150)
print("saved proofdag_layers.png")
